// Route contract for this endpoint (read by wf.gateway.auth).
const route = {"method": "POST", "template": "/v1/me/flatmate-profile/assistant", "require_user": true, "idempotent": true, "required_consents": ["terms", "privacy"], "roles": []};
const item = $input.first();
return [{ json: { ...item.json, t0: Date.now(), route }, binary: item.binary }];

// Platform endpoints (n8n/build_platform.py) > "Validate"
// One shared validator: build_platform.py writes the endpoint's spec into SPEC below at build time.
// spec = {params: {name: 'uuid' | 'int'}, query: {name: rule}, body: JSON schema | null, rules: [...]}
// rule = {type: 'int', min, max} | {type: 'bool'} | {type: 'enum', values} | {type: 'string', max, pattern} | {type: 'uuid'} | {type: 'date'}
// Output: {ok, gw, input: {params, query, body}} for the database call, or a 404/422 rejection.
// Small JSON Schema validator for LLM outputs and request bodies (spec 9.2: validate every
// output against its schema). n8n Code nodes cannot load packages (no require), so this
// covers the subset the schemas in prompts/schemas/ use: type (one or a list, including
// "null" and "integer"), enum, const, required, properties, additionalProperties (boolean
// or schema), items, minItems, maxItems, minimum, maximum, minLength, maxLength, pattern.
// Anything else in a schema is ignored. Cross-checked against the Python jsonschema package
// in tests/unit/test_prompts.py.
// Returns a list of errors [{path, issue, ...}]; empty when the value is valid.

function typeOf(v) {
  if (v === null) return 'null';
  if (Array.isArray(v)) return 'array';
  if (typeof v === 'number') return Number.isInteger(v) ? 'integer' : 'number';
  return typeof v;            // string, boolean, object
}

function typeMatches(t, v) {
  const actual = typeOf(v);
  if (t === actual) return true;
  if (t === 'number' && actual === 'integer') return true;
  return false;
}

function validate(schema, value, path = '$', errors = []) {
  if (!schema || typeof schema !== 'object') return errors;
  if (schema.type !== undefined) {
    const types = Array.isArray(schema.type) ? schema.type : [schema.type];
    if (!types.some((t) => typeMatches(t, value))) {
      errors.push({ path, issue: 'type', expected: types.join('|'), got: typeOf(value) });
      return errors;
    }
  }
  if (schema.enum !== undefined && !schema.enum.some((e) => e === value)) {
    errors.push({ path, issue: 'enum', allowed: schema.enum });
  }
  if (schema.const !== undefined && schema.const !== value) errors.push({ path, issue: 'const' });
  const t = typeOf(value);
  if (t === 'string') {
    // length in code points, as JSON Schema counts it
    const len = Array.from(value).length;
    if (schema.minLength !== undefined && len < schema.minLength) errors.push({ path, issue: 'minLength', min: schema.minLength });
    if (schema.maxLength !== undefined && len > schema.maxLength) errors.push({ path, issue: 'maxLength', max: schema.maxLength });
    if (schema.pattern !== undefined && !new RegExp(schema.pattern, 'u').test(value)) errors.push({ path, issue: 'pattern' });
  }
  if (t === 'integer' || t === 'number') {
    if (schema.minimum !== undefined && value < schema.minimum) errors.push({ path, issue: 'minimum', min: schema.minimum });
    if (schema.maximum !== undefined && value > schema.maximum) errors.push({ path, issue: 'maximum', max: schema.maximum });
  }
  if (t === 'array') {
    if (schema.minItems !== undefined && value.length < schema.minItems) errors.push({ path, issue: 'minItems', min: schema.minItems });
    if (schema.maxItems !== undefined && value.length > schema.maxItems) errors.push({ path, issue: 'maxItems', max: schema.maxItems });
    if (schema.items) value.forEach((v, i) => validate(schema.items, v, `${path}[${i}]`, errors));
  }
  if (t === 'object') {
    for (const k of schema.required || []) {
      if (!Object.prototype.hasOwnProperty.call(value, k)) errors.push({ path: `${path}.${k}`, issue: 'required' });
    }
    const props = schema.properties || {};
    for (const [k, v] of Object.entries(value)) {
      if (Object.prototype.hasOwnProperty.call(props, k)) validate(props[k], v, `${path}.${k}`, errors);
      else if (schema.additionalProperties === false) errors.push({ path: `${path}.${k}`, issue: 'additional_property' });
      else if (schema.additionalProperties && typeof schema.additionalProperties === 'object') {
        validate(schema.additionalProperties, v, `${path}.${k}`, errors);
      }
    }
  }
  return errors;
}

// One line per error, for retry prompts and logs.
function describe(errors, max = 8) {
  return errors.slice(0, max).map((e) => {
    switch (e.issue) {
      case 'type': return `${e.path}: expected ${e.expected}, got ${e.got}`;
      case 'enum': return `${e.path}: must be one of ${JSON.stringify(e.allowed)}`;
      case 'required': return `${e.path}: missing`;
      case 'additional_property': return `${e.path}: not allowed`;
      default: return `${e.path}: ${e.issue}`;
    }
  }).join('; ');
}

if (typeof module !== 'undefined') module.exports = { validate, describe, typeOf };

const SPEC = {"body": {"type": "object", "additionalProperties": false, "properties": {"text": {"type": "string", "minLength": 1, "maxLength": 2000}}, "required": ["text"]}};
const gw = $input.first().json;
const ctx = gw.ctx || {};
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const reject = (status, code, message, details = []) => [{ json: { ok: false, gw, status, error: { code, message, details } } }];

// Path parameters: a malformed id is a resource that does not exist (404), as in the /v1 GET-by-id endpoints.
const params = {};
for (const [k, t] of Object.entries(SPEC.params || {})) {
  const v = String((ctx.params || {})[k] ?? '');
  if (t === 'uuid' && !UUID.test(v)) return reject(404, 'NOT_FOUND', 'Not found');
  if (t === 'int' && !/^\d{1,18}$/.test(v)) return reject(404, 'NOT_FOUND', 'Not found');
  params[k] = t === 'uuid' ? v.toLowerCase() : v;
}

const details = [];
const query = {};
const q = ctx.query || {};
const rules = SPEC.query || {};
for (const k of Object.keys(q)) if (!(k in rules)) details.push({ field: k, issue: 'unknown_parameter' });
for (const [k, r] of Object.entries(rules)) {
  if (q[k] === undefined || q[k] === null || String(q[k]) === '') continue;
  if (Array.isArray(q[k])) { details.push({ field: k, issue: 'repeated_parameter' }); continue; }
  const v = String(q[k]).trim();
  if (r.type === 'int') {
    if (!/^-?\d{1,18}$/.test(v) || (r.min !== undefined && Number(v) < r.min) || (r.max !== undefined && Number(v) > r.max)) {
      details.push({ field: k, issue: 'out_of_range', min: r.min, max: r.max });
    } else query[k] = Number(v);
  } else if (r.type === 'bool') {
    if (!['true', 'false'].includes(v)) details.push({ field: k, issue: 'must_be_true_or_false' }); else query[k] = v === 'true';
  } else if (r.type === 'enum') {
    if (!r.values.includes(v)) details.push({ field: k, issue: 'not_allowed', allowed: r.values }); else query[k] = v;
  } else if (r.type === 'uuid') {
    if (!UUID.test(v)) details.push({ field: k, issue: 'invalid_format' }); else query[k] = v.toLowerCase();
  } else if (r.type === 'date') {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(v) || isNaN(Date.parse(v + 'T00:00:00Z'))) details.push({ field: k, issue: 'invalid_date' }); else query[k] = v;
  } else {
    if (Array.from(v).length > (r.max || 200)) details.push({ field: k, issue: 'too_long', max: r.max || 200 });
    else if (r.pattern && !new RegExp(r.pattern).test(v)) details.push({ field: k, issue: 'invalid_format' });
    else query[k] = v;
  }
}

let body = null;
if (SPEC.body) {
  body = ctx.body || {};
  for (const e of validate(SPEC.body, body)) details.push({ field: e.path.replace(/^\$\.?/, '') || 'body', issue: e.issue });
  // one of these fields must be given (JSON Schema's anyOf/required, which schema_lite does not cover)
  if (SPEC.require_any && !SPEC.require_any.some((f) => body[f] !== undefined && body[f] !== null)) {
    details.push({ field: SPEC.require_any.join('|'), issue: 'one_required' });
  }
}
if (details.length) return reject(422, 'VALIDATION_FAILED', 'Request is invalid', details);
return [{ json: { ok: true, gw, input: { params, query, body: body || {}, lang: ctx.lang || null } } }];

// wf.api.flatmate_assistant > "Agent input" (platform P12, D-115): the profile agent A7 (P13_flatmate_onboarding,
// adapted from Yosr's onboarding agent). The person's message with e-mails and phone numbers masked, the country's
// currency, and the person's language. Memory per person (session flatmate:<user>, as the Document agent's).
// A3 Match agent checks (D-084), shared by the agent workflow and the unit tests.
//  - toolCalls(steps): the AI Agent node's intermediate steps as [{tool, input, output}] (output parsed when JSON).
//  - numbersIn(text): every reading of every number written in a text (see readings).
//  - checkAnswer(answer, sources): every number of two digits or more in the answer must appear in one of the
//    sources (the user's message, the tool results). Small numbers (result positions, counts up to 10) pass.
//  - fallbackMask(text): e-mails and long digit runs masked, used only when the Text service did not answer.
//  - plainText(answer): Markdown removed (bold, italics, headings, list markers, links), lines joined (D-085).
//  - shorten(text, max): cut at the last sentence end that fits, else at a word, with an ellipsis (D-085).

function toolCalls(steps) {
  return (Array.isArray(steps) ? steps : []).map((s) => {
    const a = s.action || {};
    let out = s.observation;
    if (typeof out === 'string') { try { out = JSON.parse(out); } catch (e) { /* keep the text */ } }
    if (Array.isArray(out) && out.length === 1) out = out[0];          // a workflow tool answers with its items
    let input = a.toolInput;
    if (typeof input === 'string') { try { input = JSON.parse(input); } catch (e) { /* keep the text */ } }
    return { tool: a.tool || null, input: input ?? null, output: out ?? null };
  });
}

// Each number written in a text, with its possible readings: "450.000" is 450 (Tunisian dinars, three decimals) or
// 450000 (dot as thousands separator); "1.225.000" is 1225000; "450,5" is 450.5.
function readings(text) {
  const out = [];
  for (const m of String(text || '').matchAll(/\d{1,3}(?:\.\d{3})+(?!\d|,\d)|\d+(?:[.,]\d+)?/g)) {
    const raw = m[0];
    const alts = new Set();
    if (/^\d{1,3}(?:\.\d{3})+$/.test(raw)) alts.add(Number(raw.replace(/\./g, '')));
    const v = Number(raw.replace(',', '.'));
    if (Number.isFinite(v)) alts.add(v);
    out.push([...alts]);
  }
  return out;
}

function numbersIn(text) {
  return readings(text).flat();
}

function checkAnswer(answer, sources) {
  const allowed = new Set();
  for (const src of sources || []) {
    const text = typeof src === 'string' ? src : JSON.stringify(src ?? '');
    for (const n of numbersIn(text)) {
      allowed.add(n);
      allowed.add(Math.round(n));
    }
  }
  const unsupported = [];
  for (const alts of readings(answer)) {
    if (alts.some((n) => Number.isInteger(n) && n <= 10)) continue;
    if (alts.some((n) => allowed.has(n) || allowed.has(Math.round(n)))) continue;
    unsupported.push(alts[alts.length - 1]);
  }
  return { ok: unsupported.length === 0, unsupported };
}

function fallbackMask(text) {
  return String(text || '')
    .replace(/[\w.+-]+@[\w-]+\.[\w.-]+/g, '<EMAIL>')
    // a date written 2026-12-01 is not a phone number (F-079)
    .replace(/\+?\d[\d .-]{6,}\d/g, (m) => (/^\d{4}-\d{2}-\d{2}$/.test(m) || m.replace(/\D/g, '').length < 8 ? m : '<PHONE>'));
}

function plainText(answer) {
  const lines = String(answer || '').replace(/\r/g, '').split('\n').map((l) => l
    .replace(/^\s{0,3}#{1,6}\s+/, '')                      // headings
    .replace(/^\s*(?:[-*+\u2022]|\d+[.)])\s+/, '')            // list markers ("1." too: positions are said in words)
    .replace(/\[([^\]]+)\]\([^)]*\)/g, '$1')                // links: keep the text
    .replace(/(\*\*|__)(.+?)\1/g, '$2')                       // bold
    .replace(/(^|[^\w*])[*_]([^*_\n]+)[*_](?=[^\w*]|$)/g, '$1$2') // italics
    .replace(/`([^`]*)`/g, '$1')
    .replace(/[*_]{2,}/g, '')
    .trim()).filter(Boolean);
  return lines.join(' ').replace(/\s{2,}/g, ' ').trim();
}

function shorten(text, max) {
  const t = String(text || '');
  if (!max || Array.from(t).length <= max) return { text: t, cut: false };
  const head = Array.from(t).slice(0, max).join('');
  const ends = [...head.matchAll(/[.!?\u061F\u06D4](?=\s|$)/g)].map((m) => m.index + 1);
  if (ends.length && ends[ends.length - 1] >= max * 0.4) return { text: head.slice(0, ends[ends.length - 1]).trim(), cut: true };
  const sp = head.lastIndexOf(' ');
  return { text: (sp > max * 0.4 ? head.slice(0, sp) : head).trim() + '\u2026', cut: true };
}

if (typeof module !== 'undefined') module.exports = { toolCalls, readings, numbersIn, checkAnswer, fallbackMask, plainText, shorten };

